  "plan": "Use Python to inspect the PPM header and dimensions. Check ELF symbols for function names and disassemble main if symbols are available. Run the binary again in a clean temp directory to confirm deterministic output.",
  "commands": [
  {
    "keystrokes": "python3 - <<'PY'\nimport collections,math\nb=open('/app/image.ppm','rb').read()\nprint('size',len(b))\nprint('first100',b[:100])\nprint('repr',repr(b[:80]))\nfor n in range(1,20):\n    print(n, b[n-1:n+10])\n# try parse P6/P3\nprint('ascii head', b[:64].decode('latin1'))\nPY\n",
    "duration": 0.1
