  {
    "keystrokes": "readelf -sW mystery 2>/dev/null | grep -E 'FUNC.*main|render|image|write|ppm|mandel|julia|complex|sin|cos|sqrt|cexp|fmod' | head -100 || true\n",
    "duration": 0.1
