    "keystrokes": "rm -rf /tmp/t1 && mkdir /tmp/t1 && cd /tmp/t1 && /app/mystery >/tmp/t1/out.txt 2>/tmp/t1/err.txt; echo exit=$?; cat out.txt err.txt; ls -l image.ppm; sha256sum image.ppm\n",
    "duration": 0.1
